<html lang="en">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>Notification Preferences</title>
  <style>
    :root {
      color-scheme: light;
      --background: #f4f7fb;
      --card: #ffffff;
      --text: #152033;
      --muted: #64748b;
      --border: #dbe3ef;
      --primary: #2563eb;
      --primary-dark: #1d4ed8;
      --focus: #93c5fd;
      --shadow: 0 24px 70px rgba(15, 23, 42, 0.12);
    }

    * {
      box-sizing: border-box;
    }

    body {
      margin: 0;
      min-height: 100vh;
      font-family: Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
      color: var(--text);
      background:
        radial-gradient(circle at top left, rgba(37, 99, 235, 0.16), transparent 34rem),
        linear-gradient(135deg, #f8fbff 0%, var(--background) 100%);
    }

    .page-shell {
      display: grid;
      min-height: 100vh;
      place-items: center;
      padding: 2rem;
    }

    .card {
      width: min(100%, 34rem);
      padding: clamp(1.5rem, 4vw, 2.5rem);
      background: rgba(255, 255, 255, 0.92);
      border: 1px solid rgba(219, 227, 239, 0.9);
      border-radius: 1.5rem;
      box-shadow: var(--shadow);
      backdrop-filter: blur(18px);
    }

    .eyebrow {
      margin: 0 0 0.75rem;
      color: var(--primary);
      font-size: 0.78rem;
      font-weight: 700;
      letter-spacing: 0.12em;
      text-transform: uppercase;
    }

    h1 {
      margin: 0;
      font-size: clamp(1.75rem, 5vw, 2.5rem);
      line-height: 1.1;
      letter-spacing: -0.04em;
    }

    .intro {
      margin: 1rem 0 2rem;
      color: var(--muted);
      font-size: 1rem;
      line-height: 1.6;
    }

    .question {
      display: block;
      margin: 0 0 1rem;
      font-size: 1.05rem;
      font-weight: 700;
    }

    .radio-stack {
      display: grid;
      gap: 0.75rem;
    }

    .radio-option {
      display: flex;
      align-items: center;
      gap: 0.8rem;
      padding: 1rem;
      border: 1px solid var(--border);
      border-radius: 1rem;
      background: #ffffff;
      cursor: pointer;
      transition: border-color 180ms ease, box-shadow 180ms ease, transform 180ms ease;
    }

    .radio-option:hover {
      border-color: #b7c6db;
      transform: translateY(-1px);
    }

    .radio-option:has(input:checked) {
      border-color: var(--primary);
      box-shadow: 0 0 0 4px rgba(37, 99, 235, 0.12);
    }

    .radio-option input {
      width: 1.15rem;
      height: 1.15rem;
      margin: 0;
      accent-color: var(--primary);
    }

    .radio-option input:focus-visible {
      outline: 3px solid var(--focus);
      outline-offset: 3px;
    }

    .radio-label {
      font-weight: 650;
    }

    .submit-button {
      width: 100%;
      min-height: 3rem;
      border: 0;
      border-radius: 999px;
      color: #ffffff;
      background: var(--primary);
      font: inherit;
      font-weight: 750;
      cursor: pointer;
      box-shadow: 0 14px 30px rgba(37, 99, 235, 0.25);
      transition: background-color 180ms ease, transform 180ms ease, box-shadow 180ms ease;
    }

    .submit-button:hover {
      background: var(--primary-dark);
      transform: translateY(-1px);
      box-shadow: 0 18px 34px rgba(37, 99, 235, 0.3);
    }

    .submit-button:focus-visible {
      outline: 4px solid var(--focus);
      outline-offset: 4px;
    }
  </style>
</head>
<body>
  <div id="root"></div>

  <script>
    const notificationOptions = [
      { id: "notification-email", value: "email", label: "Email" },
      { id: "notification-sms", value: "sms", label: "SMS" },
      { id: "notification-push", value: "push", label: "Push Notifications" }
    ];

    function RadioOption({ id, value, label }) {
      return `
        <label class="radio-option" for="${id}">
          <input id="${id}" type="radio" name="notificationPreference" value="${value}" required>
          <span class="radio-label">${label}</span>
        </label>
      `;
    }

    function NotificationQuestion() {
      const options = notificationOptions.map(RadioOption).join("");

      return `
        <div class="form-field">
          <p class="question" id="notification-question">How do you prefer to receive notifications?</p>
          <div class="radio-stack" role="radiogroup" aria-labelledby="notification-question">
            ${options}
          </div>
        </div>
      `;
    }

    function NotificationForm() {
      return `
        <form aria-labelledby="page-title">
          ${NotificationQuestion()}
          <button class="submit-button" type="submit">Save preference</button>
        </form>
      `;
    }

    function App() {
      return `
        <main class="page-shell">
          <section class="card" aria-labelledby="page-title">
            <p class="eyebrow">Preferences</p>
            <h1 id="page-title">Stay in the loop</h1>
            <p class="intro">Choose the notification channel that works best for you.</p>
            ${NotificationForm()}
          </section>
        </main>
      `;
    }

    document.getElementById("root").innerHTML = App();
  </script>
</body>
</html>
